'use strict';
// A TCP echo server AND its client, both inside the island, on one loop.
//
// Every leg here is one the island's node:net has to get right for
// anything above it (node:http's own server, a driver package, a test
// harness) to work:
//   * createServer + listen(0, '127.0.0.1') — the kernel assigns the
//     port and address() reads it back only once 'listening' has fired;
//   * the accepted socket's flow control — nothing is delivered until
//     something reads it, so .on('data') is what starts the stream;
//   * setEncoding on the client, raw Buffers on the server;
//   * the half-close: server end(payload), client 'end' then 'close';
//   * setNoDelay/setKeepAlive, which must be chainable and honest;
//   * a REFUSED connect, whose error carries Node's errno name.
//
// Node is the oracle, so the ephemeral port never reaches the report.
const net = require('net');

function echoLeg(out, next) {
  const server = net.createServer((sock) => {
    out.push('server connection remote=' + typeof sock.remoteAddress +
             ' local=' + typeof sock.localPort);
    sock.on('data', (chunk) => {
      out.push('server data ' + JSON.stringify(chunk.toString('utf8')) +
               ' isBuffer=' + Buffer.isBuffer(chunk));
      sock.end('ECHO:' + chunk.toString('utf8'));
    });
    sock.on('end', () => { out.push('server end'); });
  });
  server.on('error', (e) => { out.push('server error ' + e.message); next(); });
  server.listen(0, '127.0.0.1', () => {
    const a = server.address();
    out.push('listening family=' + a.family + ' address=' + a.address +
             ' port>0=' + (a.port > 0));
    const client = net.createConnection({ port: a.port, host: '127.0.0.1' }, () => {
      out.push('client connect chain=' +
               (client.setNoDelay(true) === client) + ',' +
               (client.setKeepAlive(true) === client));
      client.write('hello');
    });
    let body = '';
    client.setEncoding('utf8');
    client.on('data', (c) => { body += c; });
    client.on('end', () => { out.push('client end body=' + JSON.stringify(body)); });
    client.on('error', (e) => { out.push('client error ' + e.message); });
    client.on('close', (hadError) => {
      out.push('client close hadError=' + hadError);
      server.close(() => { out.push('server closed'); next(); });
    });
  });
}

/** A port nothing listens on: bind, read it back, drop the listener. */
function refusedLeg(out, next) {
  const probe = net.createServer(() => {});
  probe.listen(0, '127.0.0.1', () => {
    const port = probe.address().port;
    probe.close(() => {
      const sock = net.createConnection({ port, host: '127.0.0.1' });
      sock.on('connect', () => { out.push('refused: unexpectedly connected'); });
      sock.on('error', (e) => {
        out.push('refused code=' + e.code + ' syscall=' + e.syscall);
      });
      sock.on('close', (hadError) => {
        out.push('refused close hadError=' + hadError);
        next();
      });
    });
  });
}

exports.report = function report(done) {
  const out = [];
  out.push('isIP ' + net.isIP('127.0.0.1') + ' ' + net.isIP('::1') + ' ' + net.isIP('nope'));
  echoLeg(out, () => {
    refusedLeg(out, () => { done(out.join('\n')); });
  });
};
